require_once __DIR__ . '/auth.php'; require_setting_access(); $key = trim($_POST['key'] ?? ''); $value = trim($_POST['value'] ?? ''); if ($key === '') { json_out(['success' => false, 'message' => 'Missing setting key.'], 400); } if (!in_array($key, ['restaurant_name', LOGO_SETTING_KEY], true)) { json_out(['success' => false, 'message' => 'Invalid setting key.'], 400); } if ($key === 'restaurant_name' && mb_strlen($value) > 100) { json_out(['success' => false, 'message' => 'Restaurant name too long. Maximum 100 characters.'], 400); } if ($key === LOGO_SETTING_KEY && $value !== '') { $value = ltrim(str_replace('\\', '/', $value), '/'); } if ($key === LOGO_SETTING_KEY) { save_logo_setting($value === '' ? null : $value); } else { save_setting($key, $value); } json_out(['success' => true, 'status' => 'success', 'message' => 'Setting saved.', 'key' => $key, 'value' => $value]);